@namespace sv_82999c2e6d4340f9a78bc5da9d499059.Components.Pages.Apply

<nav aria-label="Application steps" class="mb-4">
    <ol class="d-flex list-unstyled justify-content-between step-indicator">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var step = i;
            var isCompleted = CompletedSteps.Contains(step);
            var isCurrent = step == CurrentStep;
            var isClickable = isCompleted && !isCurrent;

            <li class="text-center flex-fill position-relative @(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")"
                role="button"
                @onclick="() => { if (isClickable) OnStepClicked.InvokeAsync(step); }"
                style="cursor: @(isClickable ? "pointer" : "default")">
                <div class="d-flex align-items-center justify-content-center mb-1">
                    <span class="rounded-circle d-inline-flex align-items-center justify-content-center border @(isCurrent ? "border-primary bg-primary text-white" : isCompleted ? "border-success bg-success text-white" : "border-secondary")"
                          style="width:32px;height:32px;font-size:0.85rem;">
                        @if (isCompleted && !isCurrent)
                        {
                            <span>&#10003;</span>
                        }
                        else
                        {
                            @(step + 1)
                        }
                    </span>
                </div>
                <small>@StepNames[step]</small>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

@using sv_82999c2e6d4340f9a78bc5da9d499059.Models
