@namespace sv_82999c2e6d4340f9a78bc5da9d499059.Components.Pages.Apply

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-2">
    <textarea class="form-control" rows="12"
              @bind="CoverLetter"
              @bind:event="oninput"
              @bind:after="NotifyChanged"
              maxlength="@MaxLength"
              placeholder="Write your cover letter here..."></textarea>
</div>
<div class="text-muted text-end mb-3">
    <small>@CoverLetter.Length / @MaxLength characters</small>
</div>

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next →</button>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public int MaxLength { get; set; } = 2000;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task NotifyChanged() => await CoverLetterChanged.InvokeAsync(CoverLetter);
}

@using sv_82999c2e6d4340f9a78bc5da9d499059.Models
@namespace sv_82999c2e6d4340f9a78bc5da9d499059.Components.Pages.Apply

<h4 class="mb-3">Review Your Application</h4>

@if (_submitted)
{
    <div class="alert alert-success text-center py-4">
        <h5>🎉 Application Submitted!</h5>
        <p class="mb-0">Your application ID is <strong>#@_applicationId</strong>. We'll be in touch soon.</p>
    </div>
}
else
{
    @if (!string.IsNullOrEmpty(_error))
    {
        <div class="alert alert-danger">@_error</div>
    }

    <!-- Personal Info -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Personal Information</strong>
            <a role="button" class="text-primary" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</a>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6"><strong>Name:</strong> @Form.Personal.FullName</div>
                <div class="col-md-6"><strong>Email:</strong> @Form.Personal.Email</div>
                <div class="col-md-6"><strong>Phone:</strong> @Form.Personal.Phone</div>
                <div class="col-md-6"><strong>Address:</strong> @Form.Personal.Address</div>
            </div>
        </div>
    </div>

    <!-- Work History -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Work History</strong>
            <a role="button" class="text-primary" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</a>
        </div>
        <div class="card-body">
            @foreach (var entry in Form.WorkEntries)
            {
                <div class="mb-3 pb-3 border-bottom last-child-no-border">
                    <div><strong>@entry.Title</strong> at @entry.Company</div>
                    <div class="text-muted">
                        @entry.StartDate?.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <div class="mt-1">@entry.Description</div>
                    }
                </div>
            }
        </div>
    </div>

    <!-- References -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>References</strong>
            <a role="button" class="text-primary" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</a>
        </div>
        <div class="card-body">
            @foreach (var r in Form.References)
            {
                <div class="mb-2">
                    <strong>@r.Name</strong> (@r.Relationship) — @r.Email, @r.Phone
                </div>
            }
        </div>
    </div>

    <!-- Cover Letter -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Cover Letter</strong>
            <a role="button" class="text-primary" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</a>
        </div>
        <div class="card-body">
            <p style="white-space: pre-wrap;">@Form.CoverLetter</p>
        </div>
    </div>

    <div class="d-flex justify-content-between mt-4">
        <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
        <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@_submitting">
            @if (_submitting)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                <span>Submitting…</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
}

@code {
    [Parameter, EditorRequired] public ApplicationFormModel Form { get; set; } = default!;
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnSubmitted { get; set; }

    private bool _submitting;
    private bool _submitted;
    private int _applicationId;
    private string? _error;

    [Inject] private Services.IApplicationService AppService { get; set; } = default!;

    private async Task HandleSubmit()
    {
        _error = null;
        _submitting = true;

        try
        {
            _applicationId = await AppService.SubmitApplicationAsync(Form.ToRecord());
            _submitted = true;
            await OnSubmitted.InvokeAsync(_applicationId);
        }
        catch (Exception ex)
        {
            _error = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _submitting = false;
        }
    }
}

