@page "/apply"
@rendermode InteractiveServer
@using sv_82999c2e6d4340f9a78bc5da9d499059.Models
@using sv_82999c2e6d4340f9a78bc5da9d499059.Components.Pages.Apply

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   StepNames="_stepNames"
                   OnStepClicked="GoToStep" />

    <div class="mt-3">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep Model="_form.Personal" OnNext="NextStep" />
                break;
            case 1:
                <WorkHistoryStep Entries="_form.WorkEntries" OnNext="NextStep" OnBack="PrevStep" />
                break;
            case 2:
                <ReferencesStep References="_form.References" OnNext="NextStep" OnBack="PrevStep" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@_form.CoverLetter"
                                 CoverLetterChanged="val => _form.CoverLetter = val"
                                 OnNext="NextStep"
                                 OnBack="PrevStep" />
                break;
            case 4:
                <ReviewStep Form="_form"
                            OnEditSection="GoToStep"
                            OnBack="PrevStep"
                            OnSubmitted="id => { }" />
                break;
        }
    </div>
</div>

@code {
    private readonly ApplicationFormModel _form = new();
    private int _currentStep;
    private readonly HashSet<int> _completedSteps = [];

    private static readonly List<string> _stepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];

    private void NextStep()
    {
        _completedSteps.Add(_currentStep);
        if (_currentStep < _stepNames.Count - 1)
            _currentStep++;
    }

    private void PrevStep()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step >= 0 && step < _stepNames.Count)
            _currentStep = step;
    }
}

